// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, uint256 seed) public {
        vm.assume(amount > 0);
        uint256 funding = amount;
        vm.deal(address(c), funding);
        assert(address(c).balance >= amount);

        bool ok;
        try c.withdraw(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok || address(c).balance < funding);
    }
}
